    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    cursor: pointer;
  }
  .cal-event-all-day a {
    color: inherit;
    text-decoration: none;
  }
  .cal-event-all-day a:hover {
    text-decoration: underline;
  }
  .cal-event-classical {
    position: relative;
    padding-left: 10px;
  }
  /* Phase 33 Plan 02 (ANNOT-02, D-10/D-11): compact campaign-attribution marker.
     color: currentColor -- an all-day entry sets its own foreground inline via the
     text_color_for_bg WCAG-AA computation against the proposal fill; inheriting
     currentColor keeps the chip legible on every proposal fill, the neutral classical
     fill, and the white cell alike, instead of failing contrast on a dark fill like
     #005f9e / #5b2080 / #9e1c1c with a hard-coded glyph colour (33-REVIEWS.md Agreed
     Concern 6).
     flex-shrink: 0 -- .cal-event-timed is display flex with .cal-event-title already
     flex 1 and min-width 0; without this the chip is a shrinkable flex item and gets
     squeezed or clipped in a narrow day cell. */
  .cal-campaign-chip {
    color: currentColor;
    flex-shrink: 0;
    margin-right: 2px;
    font-size: 0.7rem;
    line-height: 1;
  }
  .cal-event-classical::before {
    /* quick-260724-vb0: the stripe's outward-facing sides (left/top/bottom, which
       border the white day cell -- and, on a terminal-status chip, the composited
       status ring) get a 1px opaque edge in STRIPE_OUTER_EDGE_COLOR (#343a40, the
       Python-side mirror of this color). The fill-facing (right) side gets none,
       because every TELESCOPE_STRIPE_PALETTE entry already clears 3:1 against the
       chip's own NEUTRAL_SLOT_COLOR fill there on its own -- see
       TestTelescopeStripeContrast for the band arithmetic that justifies leaving
       that side bare. */
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 7px;
    background-color: var(--tel-color);
    box-shadow:
      inset 1px 1px 0 0 #343a40,
      inset 0 -1px 0 0 #343a40;
    border-radius: 3px 0 0 3px;
  }
  .cal-legend-chip {
    display: inline-block;
    width: 12px;
    height: 12px;
    border-radius: 3px;
    margin-right: 2px;
    vertical-align: middle;
  }
  .cal-legend-swatch {
    cursor: pointer;
    user-select: none;
    font-size: 1rem;
    line-height: 1;
    transition: opacity 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
  }
  .cal-legend-swatch.is-active {
    font-weight: 700;
    text-decoration: underline;
  }
  .cal-legend-telescope {
    font-size: 1rem;
    line-height: 1;
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
  }
  .cal-event {
    transition: opacity 0.2s, filter 0.2s;
  }
  #calendar-partial.cal-filtering .cal-event {
    opacity: 0.18;
    filter: grayscale(50%);
  }
  #calendar-partial.cal-filtering .cal-event.cal-filter-match {
    opacity: 1;
    filter: none;
  }
  /* D-13 (Phase 37 Plan 06, UNUSED-01): style-only channel for an unused awarded night --
     reduced opacity plus a dashed border, distinct at a glance from a realised night. The
     [U] text token (prepended to the title below) is the OTHER channel; this rule never
     replaces it, and D-13 explicitly forbids a fourth status_border_css() ring colour for
     this state, so no box-shadow is added here. */
  .cal-event-unused {
