  <script>
  (function () {
    var container = document.getElementById('calendar-partial');
    if (!container) return;
    // D-15 (Phase 37 Plan 06): one shared toggle serves both filter kinds -- a click on a
    // proposal swatch still filters on data-proposal exactly as before; a click on the
    // legend's [U] entry (data-filter="unused") toggles cal-filter-match on elements
    // carrying the data-unused flag instead. activeFilter is null, or {kind: 'proposal', value}
    // or {kind: 'unused'} -- the existing single-active-filter behaviour (clicking the
    // active entry clears it) is unchanged, just generalized over which kind is active.
    var activeFilter = null;
    function filterForSwatch(swatch) {
      if (swatch.dataset.filter === 'unused') {
        return {kind: 'unused'};
      }
      return {kind: 'proposal', value: swatch.dataset.proposal};
    }
    function sameFilter(a, b) {
      if (!a || !b) return false;
      return a.kind === b.kind && a.value === b.value;
    }
    function eventMatchesFilter(el, filter) {
      if (filter.kind === 'unused') return el.dataset.unused === '1';
      return (el.dataset.proposal || '') === filter.value;
    }
    container.addEventListener('click', function (e) {
      var swatch = e.target.closest('.cal-legend-swatch');
      if (!swatch) return;
      var filter = filterForSwatch(swatch);
      if (sameFilter(activeFilter, filter)) {
        activeFilter = null;
        container.classList.remove('cal-filtering');
        container.querySelectorAll('.cal-event').forEach(function (el) { el.classList.remove('cal-filter-match'); });
        container.querySelectorAll('.cal-legend-swatch').forEach(function (el) { el.classList.remove('is-active'); });
      } else {
        activeFilter = filter;
        container.classList.add('cal-filtering');
        container.querySelectorAll('.cal-event').forEach(function (el) {
          el.classList.toggle('cal-filter-match', eventMatchesFilter(el, filter));
        });
        container.querySelectorAll('.cal-legend-swatch').forEach(function (el) {
          el.classList.toggle('is-active', sameFilter(filterForSwatch(el), filter));
        });
      }
    });
  }());
  </script>
